    getIndexerStatus: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Indexer status information */
            200: {
                headers: {
                    /** @description Current crawling status: 'active' or 'stopped' */
                    "X-Crawling-Status"?: "active" | "stopped";
                    /** @description Current indexer status: 'running' or 'stopped' */
                    "X-Indexer-Status"?: "running" | "stopped";
                    /** @description Reason why crawling stopped (only present when crawling is stopped) */
                    "X-Crawling-Reason"?: string;
                    /** @description Error message that caused crawling to stop (only present when crawling is stopped) */
                    "X-Crawling-Error"?: string;
                    /** @description ISO 8601 timestamp when crawling stopped (only present when crawling is stopped) */
                    "X-Crawling-Stopped-At"?: string;
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "is_running": true,
                     *       "is_crawling": false,
                     *       "stopped_at": "2024-01-15T10:30:00Z",
                     *       "stopped_reason": "Crawling stopped due to: Unknown Verana message types: /verana.pp.v1.MsgCreateRootParticipant. Indexer APIs remain available.",
                     *       "last_error": {
                     *         "message": "Unknown Verana message types: /verana.pp.v1.MsgCreateRootParticipant",
                     *         "timestamp": "2024-01-15T10:30:00Z",
                     *         "service": "crawl-tx"
                     *       }
                     *     }
                     */
                    "application/json": {
                        /**
                         * @description Whether the indexer service is running. If false, all APIs will return 503.
                         * @example true
                         */
                        is_running: boolean;
                        /**
                         * @description Whether the indexer is actively crawling new blocks and transactions. If false, APIs remain available but no new data is being indexed.
                         * @example false
                         */
                        is_crawling: boolean;
                        /**
                         * Format: date-time
                         * @description ISO 8601 timestamp when the indexer or crawling stopped (if applicable)
                         * @example 2024-01-15T10:30:00Z
                         */
                        stopped_at?: string;
                        /**
                         * @description Human-readable reason why crawling or the indexer stopped (if applicable)
                         * @example Crawling stopped due to: Unknown Verana message types: /verana.pp.v1.MsgCreateRootParticipant. Indexer APIs remain available.
                         */
                        stopped_reason?: string;
                        /** @description Details about the last error that caused crawling or indexer to stop (if applicable) */
                        last_error?: {
                            /**
                             * @description Error message
                             * @example Unknown Verana message types: /verana.pp.v1.MsgCreateRootParticipant
                             */
                            message?: string;
                            /**
                             * @description Error stack trace (if available)
                             * @example Error: Unknown Verana message types...
                             *         at ...
                             */
                            stack?: string;
                            /**
                             * Format: date-time
                             * @description When the error occurred
                             * @example 2024-01-15T10:30:00Z
                             */
                            timestamp?: string;
                            /**
                             * @description Service name where the error occurred
                             * @example crawl-tx
                             */
                            service?: string;
                        };
                    };
                };
            };
            500: components["responses"]["ServerError"];
        };
    };
